import React, { useState, useRef, useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { Form, Input, Button, Tabs, Typography, message, Checkbox } from "antd";
import {
  RobotOutlined,
  UserOutlined,
  LockOutlined,
  MailOutlined,
  HomeOutlined,
} from "@ant-design/icons";
import gsap from "gsap";
import { SplitText } from "gsap/SplitText";
import { authApi, teacherAuthApi } from "../services/api";
import { useAppStore } from "../store";
import { extractApiError } from "../utils/error";

const LOGIN_BG =
  "data:image/jpeg;base64,";

const tabItems = [
  { key: "login", label: "登录" },
  { key: "register", label: "学生注册" },
  { key: "teacher-register", label: "教师注册" },
];

const Login: React.FC = () => {
  const navigate = useNavigate();
  const login = useAppStore((s) => s.login);
  const setUserInfo = useAppStore((s) => s.setUserInfo);
  const [activeTab, setActiveTab] = useState("login");
  const [loading, setLoading] = useState(false);

  const titleRef = useRef<HTMLHeadingElement>(null);

  useEffect(() => {
    const titleEl = titleRef.current;
    if (!titleEl) return;

    const splits: Array<{ revert: () => void; lines: Element[] }> = [];
    const allBlocks: HTMLDivElement[] = [];
    const allLines: HTMLElement[] = [];

    const split = new SplitText(titleEl, {
      type: "lines",
      linesClass: "block-line++",
      lineThreshold: 0.1,
    });
    splits.push(split);

    split.lines.forEach((line: Element) => {
      const el = line as HTMLElement;
      const wrapper = document.createElement("div");
      wrapper.className = "block-line-wrapper";
      el.parentNode?.insertBefore(wrapper, el);
      wrapper.appendChild(el);

      const block = document.createElement("div");
      block.className = "block-revealer";
      block.style.backgroundColor = "#cbd5e1";
      wrapper.appendChild(block);

      allLines.push(el);
      allBlocks.push(block);
    });

    gsap.set(allLines, { opacity: 0 });
    gsap.set(allBlocks, { scaleX: 0, transformOrigin: "left center" });

    allBlocks.forEach((block, index) => {
      const tl = gsap.timeline({ delay: 0.3 + index * 0.15 });
      tl.to(block, {
        scaleX: 1,
        duration: 0.75,
        ease: "power4.inOut",
      });
      tl.set(allLines[index], { opacity: 1 });
      tl.set(block, { transformOrigin: "right center" });
      tl.to(block, {
        scaleX: 0,
        duration: 0.75,
        ease: "power4.inOut",
      });
    });

    return () => {
      splits.forEach((s) => s.revert());
      const section = titleEl.closest("div");
      if (section) {
        const wrappers = section.querySelectorAll(".block-line-wrapper");
        wrappers.forEach((wrapper) => {
          if (wrapper.parentNode && wrapper.firstChild) {
            wrapper.parentNode.insertBefore(wrapper.firstChild, wrapper);
            wrapper.remove();
          }
        });
      }
    };
  }, []);

  const handleLogin = async (values: {
    student_id: string;
    password: string;
  }) => {
    setLoading(true);
    try {
      const res = await authApi.login(values);
      const token = res.data?.access_token;
      if (!token) {
        message.error("登录失败：未获取到令牌");
        return;
      }
      login(token, values.student_id);

      let role = "student";
      try {
        const meRes = await authApi.me();
        const u = meRes.data?.data;
        role = u.role;
        setUserInfo({
          student_id: u.student_id,
          username: u.username,
          role: u.role,
        });
      } catch {
        // ignore
      }

      message.success("登录成功");
      navigate(role === "teacher" || role === "admin" ? "/teacher" : "/");
    } catch (e: unknown) {
      message.error(extractApiError(e, "登录失败"));
    } finally {
      setLoading(false);
    }
  };

  const handleRegister = async (values: {
    student_id: string;
    username: string;
    email?: string;
    password: string;
  }) => {
    setLoading(true);
    try {
      await authApi.register(values);
      message.success("注册成功，请登录");
      setActiveTab("login");
    } catch (e: unknown) {
      message.error(extractApiError(e, "注册失败"));
    } finally {
      setLoading(false);
    }
  };

  const handleTeacherRegister = async (values: {
    student_id: string;
    username: string;
    email?: string;
    password: string;
  }) => {
    setLoading(true);
    try {
      await teacherAuthApi.register(values);
      message.success("教师注册成功，请登录");
      setActiveTab("login");
    } catch (e: unknown) {
      message.error(extractApiError(e, "注册失败"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen relative flex">
      {/* 背景 */}
      <div
        className="absolute inset-0 bg-cover bg-center bg-no-repeat"
        style={{ backgroundImage: `url(${LOGIN_BG})` }}
      />

      {/* 返回主页按钮 */}
      <Button
        type="text"
        icon={<HomeOutlined />}
        onClick={() => navigate("/")}
        className="absolute top-4 left-4 z-20 text-slate-600 hover:text-primary hover:bg-white/50"
        size="large"
      >
        返回主页
      </Button>

      {/* 内容区 */}
      <div className="relative z-10 flex flex-col lg:flex-row w-full min-h-screen">
        {/* ===== 左侧：品牌标语 ===== */}
        <div className="hidden lg:flex w-1/2 items-center justify-center px-12 xl:px-20">
          <div className="max-w-lg">
            <h1
              ref={titleRef}
              className="text-4xl xl:text-5xl font-bold text-slate-800 leading-tight tracking-tight"
            >
              AI 驱动的个性化学习，点亮知识新边界
            </h1>
          </div>
        </div>

        {/* ===== 右侧：登录模块 ===== */}
        <div className="w-full lg:w-1/2 flex items-center justify-center px-6 py-12">
          <div className="w-full max-w-lg">
            {/* 登录卡片 */}
            <div className="bg-white/90 backdrop-blur-sm rounded-2xl shadow-xl border border-white/50 px-10 py-20 min-h-[520px]">
              <Tabs
                activeKey={activeTab}
                onChange={setActiveTab}
                centered
                className="mb-6"
                items={tabItems}
              />

              {activeTab === "login" && (
                <Form layout="vertical" onFinish={handleLogin} size="large">
                  <Form.Item
                    name="student_id"
                    rules={[{ required: true, message: "请输入学号" }]}
                  >
                    <Input
                      prefix={<UserOutlined className="text-slate-400" />}
                      placeholder="学号 / 工号"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item
                    name="password"
                    rules={[{ required: true, message: "请输入密码" }]}
                  >
                    <Input.Password
                      prefix={<LockOutlined className="text-slate-400" />}
                      placeholder="输入密码"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item className="mb-4">
                    <div className="flex items-center justify-between">
                      <Checkbox>30天内免登录</Checkbox>
                    </div>
                  </Form.Item>
                  <Form.Item className="mb-0">
                    <Button
                      type="primary"
                      htmlType="submit"
                      block
                      loading={loading}
                      className="rounded-lg bg-primary h-11 text-base font-semibold"
                    >
                      登 录
                    </Button>
                  </Form.Item>
                </Form>
              )}

              {activeTab === "register" && (
                <Form layout="vertical" onFinish={handleRegister} size="large">
                  <Form.Item
                    name="student_id"
                    rules={[{ required: true, message: "请输入学号" }]}
                  >
                    <Input
                      prefix={<UserOutlined className="text-slate-400" />}
                      placeholder="请输入学号"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item
                    name="username"
                    rules={[{ required: true, message: "请输入用户名" }]}
                  >
                    <Input
                      prefix={<UserOutlined className="text-slate-400" />}
                      placeholder="请输入用户名"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item name="email">
                    <Input
                      prefix={<MailOutlined className="text-slate-400" />}
                      placeholder="请输入邮箱（可选）"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item
                    name="password"
                    rules={[
                      { required: true, message: "请输入密码" },
                      { min: 8, message: "密码至少8位" },
                      {
                        pattern: /^(?=.*[A-Za-z])(?=.*\d).+$/,
                        message: "密码必须包含字母和数字",
                      },
                    ]}
                  >
                    <Input.Password
                      prefix={<LockOutlined className="text-slate-400" />}
                      placeholder="请输入密码"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item className="mb-0">
                    <Button
                      type="primary"
                      htmlType="submit"
                      block
                      loading={loading}
                      className="rounded-lg bg-primary h-11 text-base font-semibold"
                    >
                      注 册
                    </Button>
                  </Form.Item>
                </Form>
              )}

              {activeTab === "teacher-register" && (
                <Form
                  layout="vertical"
                  onFinish={handleTeacherRegister}
                  size="large"
                >
                  <Form.Item
                    name="student_id"
                    rules={[{ required: true, message: "请输入工号" }]}
                  >
                    <Input
                      prefix={<UserOutlined className="text-slate-400" />}
                      placeholder="请输入工号"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item
                    name="username"
                    rules={[{ required: true, message: "请输入姓名" }]}
                  >
                    <Input
                      prefix={<UserOutlined className="text-slate-400" />}
                      placeholder="请输入姓名"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item name="email">
                    <Input
                      prefix={<MailOutlined className="text-slate-400" />}
                      placeholder="请输入邮箱（可选）"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item
                    name="password"
                    rules={[
                      { required: true, message: "请输入密码" },
                      { min: 8, message: "密码至少8位" },
                      {
                        pattern: /^(?=.*[A-Za-z])(?=.*\d).+$/,
                        message: "密码必须包含字母和数字",
                      },
                    ]}
                  >
                    <Input.Password
                      prefix={<LockOutlined className="text-slate-400" />}
                      placeholder="请输入密码"
                      className="rounded-lg"
                    />
                  </Form.Item>
                  <Form.Item className="mb-0">
                    <Button
                      type="primary"
                      htmlType="submit"
                      block
                      loading={loading}
                      className="rounded-lg bg-primary h-11 text-base font-semibold"
                    >
                      教师注册
                    </Button>
                  </Form.Item>
                </Form>
              )}

              {/* 底部链接 */}
              <div className="mt-6 text-center">
                {activeTab === "login" ? (
                  <span className="text-sm text-slate-400">
                    还没有帐号？
                    <Button
                      type="link"
                      size="small"
                      className="text-primary font-medium"
                      onClick={() => setActiveTab("register")}
                    >
                      立即注册
                    </Button>
                  </span>
                ) : (
                  <span className="text-sm text-slate-400">
                    已有帐号？
                    <Button
                      type="link"
                      size="small"
                      className="text-primary font-medium"
                      onClick={() => setActiveTab("login")}
                    >
                      立即登录
                    </Button>
                  </span>
                )}
              </div>
            </div>

            {import.meta.env.DEV && (
              <div className="text-center mt-4 text-slate-400 text-xs">
                <p>测试账号：student_001 / 123456</p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default Login;
